-- SQL: load 'Математика (пробный тест 01)' into the question bank
-- Run in Supabase SQL Editor after 016_question_bank.sql

with new_test as (
  insert into question_bank_tests (code, profile_id, title, status)
  values ('test_math_generated_01', 'nish_math', 'Математика (пробный тест 01)', 'draft')
  returning id
)
insert into question_bank_items (test_id, question_number, block_key, text_kk, text_ru, answer_format, choices, image_svg)
select id, v.question_number, 'main', v.text_kk, v.text_ru, 'abcd', v.choices::jsonb, v.image_svg
from new_test, (values
  (1, 'Ұзындығы 18м болатын сым ұзындықтары 2:3:4 қатынасындай болатын үш бөлікке бөлінді. Сымның ең ұзын бөлігін табыңыз.', 'Проволока длиной 18 м была разделена на три части, длины которых относятся как 2:3:4. Найдите самую длинную часть проволоки.', '[{"text": "6", "correct": false}, {"text": "8", "correct": true}, {"text": "4", "correct": false}, {"text": "10", "correct": false}]', NULL),
  (2, 'Кітап 210 беттен тұрады. Оқушы бірінші күні кітаптың 2/5 бөлігін, ал екінші күні 1/3 бөлігін оқыды. Қанша бет оқылмады?', 'Книга состоит из 210 страниц. Ученик прочитал в первый день 2/5 книги, а во второй день 1/3 книги. Сколько страниц осталось непрочитанными?', '[{"text": "56", "correct": true}, {"text": "70", "correct": false}, {"text": "84", "correct": false}, {"text": "42", "correct": false}]', NULL),
  (3, 'Есептеңіз:

( -5/12 ) × ( -8/5 ) × ( -12/8 ) + ( -9/16 ) × ( -16/9 ) - 3/4', 'Вычислите:

( -5/12 ) × ( -8/5 ) × ( -12/8 ) + ( -9/16 ) × ( -16/9 ) - 3/4', '[{"text": "-3/4", "correct": true}, {"text": "3/4", "correct": false}, {"text": "-1/4", "correct": false}, {"text": "0", "correct": false}]', NULL),
  (4, 'Екі жұмысшы бірге жұмыс істесе, тапсырманы 12 сағатта орындайды. Біріншісі жалғыз жұмыс істесе, екіншісіне қарағанда 4 сағатқа тезірек орындайды. Егер бірінші жұмысшы тапсырманы жалғыз өзі x сағатта орындай алса, дұрыс құрастырылған теңдеуді табыңыз.', 'Два рабочих, работая вместе, выполняют задание за 12 часов. Первый, работая один, выполнил бы задание на 4 часа быстрее второго. Если первый рабочий, работая один, может выполнить задание за x часов, найдите правильно составленное уравнение.', '[{"text": "x+4+x=1/12", "correct": false}, {"text": "1/x+1/(x+4)=1/12", "correct": true}, {"text": "1/x+1/(x+4)=12", "correct": false}, {"text": "x+4+x=12", "correct": false}]', NULL),
  (5, 'Пойыз 90км/сағ жылдамдықпен 4 сағ жүрді. Дәл сол қашықтықты 120км/сағ жылдамдықпен пойыз қанша сағат жүреді?', 'Поезд двигался со скоростью 90 км/ч в течение 4 часов. За какое время поезд преодолеет то же расстояние, если его скорость будет 120 км/ч?', '[{"text": "4", "correct": false}, {"text": "3", "correct": true}, {"text": "5", "correct": false}, {"text": "6", "correct": false}]', NULL),
  (6, 'Ұзындығы 18π см шеңбердің диаметрі қандай?', 'Какова длина диаметра окружности, длина которой равна 18π см?', '[{"text": "9см", "correct": false}, {"text": "18см", "correct": true}, {"text": "6см", "correct": false}, {"text": "36см", "correct": false}]', NULL),
  (7, 'Қатардың келесі мүшесін табыңыз: 4; 2; 4/3; 1; 4/5; ?', 'Найдите следующий член последовательности: 4; 2; 4/3; 1; 4/5; ?', '[{"text": "4/6", "correct": false}, {"text": "2/3", "correct": true}, {"text": "4/7", "correct": false}, {"text": "1/2", "correct": false}]', NULL),
  (8, 'Жазыңқы бұрыштың 3/8 бөлігін құрайтын бұрыштың градустық өлшемі қандай?', 'Какова градусная мера угла, если она составляет 3/8 развернутого угла?', '[{"text": "67,5", "correct": true}, {"text": "60", "correct": false}, {"text": "70", "correct": false}, {"text": "75", "correct": false}]', NULL),
  (9, 'Берілген сандар аралығына кіретін бүтін сандардың қосындысын табыңыз: [-12 2/3; 9,4]', 'Найдите сумму целых чисел, входящих в заданный числовой промежуток: [-12 2/3; 9,4]', '[{"text": "-30", "correct": false}, {"text": "-33", "correct": true}, {"text": "-36", "correct": false}, {"text": "-28", "correct": false}]', NULL),
  (10, 'ЕКОК (48;60;72)', 'НОК (48;60;72)', '[{"text": "360", "correct": false}, {"text": "480", "correct": false}, {"text": "720", "correct": true}, {"text": "240", "correct": false}]', NULL),
  (11, 'Есептеңіз: -3/4 - ( 25/12 - 17/24 )', 'Вычислите: -3/4 - ( 25/12 - 17/24 )', '[{"text": "-15/8", "correct": true}, {"text": "15/8", "correct": false}, {"text": "-7/8", "correct": false}, {"text": "-9/8", "correct": false}]', NULL),
  (12, 'Диаметрі 60 см болатын дөңгелек 25 рет айналса неше метрге жетеді? π=3,14', 'Если круг диаметром 60 см совершает 25 оборотов, какое расстояние (в метрах) он пройдёт? π=3,14', '[{"text": "47,1", "correct": true}, {"text": "4,71", "correct": false}, {"text": "471", "correct": false}, {"text": "23,55", "correct": false}]', NULL),
  (13, 'Боялған бөліктің ауданын табыңыз.

![](figs/q13.png)', 'Найдите площадь закрашенной части.

![](figs/q13.png)', '[{"text": "72", "correct": true}, {"text": "80", "correct": false}, {"text": "68", "correct": false}, {"text": "76", "correct": false}]', '<svg viewBox="0 0 260 220" xmlns="http://www.w3.org/2000/svg"><polygon points="20,20 220,20 220,100 140,180 20,180" fill="#d9d9d9" stroke="black" stroke-width="2"/><text x="4" y="104" font-size="16">8</text><text x="110" y="200" font-size="16">10</text><text x="225" y="145" font-size="14">4</text><text x="165" y="200" font-size="14">4</text></svg>'),
  (14, '3 пен x-тің қосындысын 3-ке көбейткенде -21-ге тең болады. x-ті табыңыз.', 'Сумма 5 и x, умноженная на 3, равна -21. Найдите x.', '[{"text": "-12", "correct": true}, {"text": "-2", "correct": false}, {"text": "-7", "correct": false}, {"text": "12", "correct": false}]', NULL),
  (15, 'Фигураның ауданын табыңыз.

![](figs/q15.png)', 'Найдите площадь фигуры.

![](figs/q15.png)', '[{"text": "96", "correct": false}, {"text": "81", "correct": true}, {"text": "75", "correct": false}, {"text": "84", "correct": false}]', '<svg viewBox="0 0 230 170" xmlns="http://www.w3.org/2000/svg"><polygon points="20,20 125,20 125,65 200,65 200,140 20,140" fill="#d9d9d9" stroke="black" stroke-width="2"/><text x="100" y="14" font-size="13">7</text><text x="4" y="85" font-size="13">8</text><text x="205" y="105" font-size="13">5</text><text x="155" y="58" font-size="11">3</text><text x="100" y="155" font-size="13">12</text></svg>'),
  (16, 'Хауызды екі құбырмен толтыруға болады. Екі құбыр бірге 12 сағатта толтырады. Екі құбыр бірге 5 сағатта хауыздың қандай бөлігін толтырады?', 'Бассейн можно наполнить двумя трубами. Обе трубы вместе наполняют бассейн за 12 часов. Какую часть бассейна заполнят обе трубы вместе за 5 часов?', '[{"text": "5/12", "correct": true}, {"text": "5/7", "correct": false}, {"text": "7/12", "correct": false}, {"text": "1/2", "correct": false}]', NULL),
  (17, 'Теңдеудің түбірлерінің қосындысын табыңыз: (|x-7|)/5 = 6,4/8', 'Найдите сумму корней уравнения: (|x-7|)/5 = 6,4/8', '[{"text": "14", "correct": true}, {"text": "-14", "correct": false}, {"text": "7", "correct": false}, {"text": "10", "correct": false}]', NULL),
  (18, '22,5-тің 12%-ын емес, 48-дің 15%-ын табыңыз.', 'Найдите 15% от 48.', '[{"text": "7,2", "correct": true}, {"text": "6,4", "correct": false}, {"text": "8", "correct": false}, {"text": "7,5", "correct": false}]', NULL),
  (19, '240-тің 5/12-ін табыңыз.', 'Найдите 5/12 от 240.', '[{"text": "80", "correct": false}, {"text": "100", "correct": true}, {"text": "96", "correct": false}, {"text": "120", "correct": false}]', NULL),
  (20, 'Ықшамдаңыз: 8x - 4(x-9)', 'Упростите: 8x - 4(x-9)', '[{"text": "4x+36", "correct": true}, {"text": "4x-36", "correct": false}, {"text": "12x-36", "correct": false}, {"text": "4x+9", "correct": false}]', NULL),
  (21, 'a/b=4/3 болса, b/(2a+3b) табыңыз.', 'Если a/b=4/3, найдите b/(2a+3b).', '[{"text": "3/17", "correct": true}, {"text": "4/17", "correct": false}, {"text": "3/11", "correct": false}, {"text": "1/2", "correct": false}]', NULL),
  (22, 'Кітаптың дүкендегі бағасы оның көтерме бағасынан 25%-ға қымбат. Егер кітаптың көтерме бағасы 1840 теңге болса, дүкендегі бағасы қандай?', 'Цена книги в магазине на 25% выше оптовой цены. Если оптовая цена книги составляет 1840 тенге, какова цена книги в магазине?', '[{"text": "2300", "correct": true}, {"text": "2250", "correct": false}, {"text": "2400", "correct": false}, {"text": "2185", "correct": false}]', NULL),
  (23, 'Үшбұрыштың периметрі 90см. Қабырға ұзындықтары 5, 6, 7 сандарына пропорционал. Ең үлкен және ең қысқа қабырғаларының айырмасын табыңыз.', 'Периметр треугольника равен 90 см. Длины его сторон пропорциональны числам 5, 6 и 7. Найдите разность между самой большой и самой маленькой сторонами.', '[{"text": "10", "correct": true}, {"text": "15", "correct": false}, {"text": "12", "correct": false}, {"text": "18", "correct": false}]', NULL),
  (24, '42 санын жай сандардың көбейтіндісі түрінде өрнектеңіз.', 'Разложите число 42 на множители, представляя его в виде произведения простых чисел.', '[{"text": "2 × 21", "correct": false}, {"text": "2 × 3 × 7", "correct": true}, {"text": "6 × 7", "correct": false}, {"text": "3 × 14", "correct": false}]', NULL),
  (25, '18 минут 1 сағаттың қанша процентін құрайды?', 'Сколько процентов составляет 18 минут от 1 часа?', '[{"text": "25%", "correct": false}, {"text": "30%", "correct": true}, {"text": "35%", "correct": false}, {"text": "20%", "correct": false}]', NULL),
  (26, '5/8 = 9/(4-a)', '5/8 = 9/(4-a)', '[{"text": "-10,4", "correct": true}, {"text": "10,4", "correct": false}, {"text": "-8,4", "correct": false}, {"text": "8,4", "correct": false}]', NULL),
  (27, 'Қабырғасы 3см болатын шаршылардан құралған фигураның периметрін табыңыз.

![](figs/q27.png)', 'Найдите периметр фигуры, составленной из квадратов со стороной 3 см.

![](figs/q27.png)', '[{"text": "30", "correct": false}, {"text": "36", "correct": true}, {"text": "42", "correct": false}, {"text": "24", "correct": false}]', '<svg viewBox="0 0 160 100" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="50" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="50" y="50" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="80" y="50" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="80" y="20" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="110" y="20" width="30" height="30" fill="#d9d9d9" stroke="black"/></svg>'),
  (28, 'x/4,5 = 5,4/0,9', 'x/4,5 = 5,4/0,9', '[{"text": "27", "correct": true}, {"text": "24", "correct": false}, {"text": "30", "correct": false}, {"text": "25", "correct": false}]', NULL),
  (29, 'Асанның жылдамдығы 90км/сағ. Ол 3 сағат жүргеннен соң оның артынан 120км/сағ жылдамдықпен Үсен шықты. Үсен Асанды қанша уақытта қуып жетеді?', 'Скорость Асана составляет 90 км/ч. Через 3 часа после его выезда Усен отправился следом со скоростью 120 км/ч. Через какое время Усен догонит Асана?', '[{"text": "9", "correct": true}, {"text": "8", "correct": false}, {"text": "10", "correct": false}, {"text": "6", "correct": false}]', NULL),
  (30, 'Қатардың келесі мүшесін табыңыз: 2; 5; 10; 17; 26; ?', 'Найдите следующий член последовательности: 2; 5; 10; 17; 26; ?', '[{"text": "35", "correct": false}, {"text": "37", "correct": true}, {"text": "39", "correct": false}, {"text": "33", "correct": false}]', NULL),
  (31, 'Сағат 3:40 көрсетіп тұр. Сағат тілдерінің арасындағы бұрыш неше градусты құрайды?', 'Часы показывают 3:40. Сколько градусов составляет угол между стрелками часов?', '[{"text": "130", "correct": true}, {"text": "120", "correct": false}, {"text": "125", "correct": false}, {"text": "135", "correct": false}]', NULL),
  (32, 'А нүктесінің координатасы (1,4). А нүктесінен 5 бірлік қашықтықта, координаталары (4,8) нүктесі жатыр ма?', 'Координата точки А (1,4). Найдите расстояние от точки А до точки с координатами (4,8).', '[{"text": "4", "correct": false}, {"text": "5", "correct": true}, {"text": "6", "correct": false}, {"text": "7", "correct": false}]', NULL),
  (33, 'Теңдеудің неше түбірі бар? | |x| - 6 | = 4', 'Сколько корней имеет уравнение? | |x| - 6 | = 4', '[{"text": "2", "correct": false}, {"text": "3", "correct": false}, {"text": "4", "correct": true}, {"text": "5", "correct": false}]', NULL),
  (34, 'n санын x арқылы өрнектеңіз: (n-8)/5 = x+3', 'Выразите число n через число x: (n-8)/5 = x+3', '[{"text": "n=5x+23", "correct": true}, {"text": "n=5x-23", "correct": false}, {"text": "n=5x+7", "correct": false}, {"text": "n=0,2x+3,6", "correct": false}]', NULL),
  (35, 'Тіктөртбұрыштың ұзындығының еніне қатынасы 8:5. Ұзындығы енінен 12 см-ге артық. Тіктөртбұрыштың периметрін табыңыз.', 'Отношение длины к ширине прямоугольника как 8:5. Длина на 12 см больше, чем ширина. Найдите периметр прямоугольника.', '[{"text": "100", "correct": false}, {"text": "104", "correct": true}, {"text": "108", "correct": false}, {"text": "96", "correct": false}]', NULL),
  (36, 'Екі жұмысшы бірге орды 8 сағатта қазады. Біріншісі жалғыз қазса, екіншісіне қарағанда 4 сағатқа тезірек орындайды. Егер бірінші жұмысшы жалғыз x сағатта орындай алса, дұрыс құрастырылған теңдеуді табыңыз.', 'Два рабочих вместе выкапывают траншею за 8 часов. Первый, работая один, выполнил бы задание на 4 часа быстрее второго. Если первый рабочий, работая один, может выполнить задание за x часов, найдите правильно составленное уравнение.', '[{"text": "1/x+1/(x+4)=1/8", "correct": true}, {"text": "x+4+x=1/8", "correct": false}, {"text": "1/x+1/(x+4)=8", "correct": false}, {"text": "x-4+x=8", "correct": false}]', NULL),
  (37, 'Ықшамдаңыз: 5(2x-3) - 3(x-4)', 'Упростите: 5(2x-3) - 3(x-4)', '[{"text": "7x-3", "correct": true}, {"text": "7x+3", "correct": false}, {"text": "7x-27", "correct": false}, {"text": "13x-27", "correct": false}]', NULL),
  (38, 'Тауардың бағасы алдымен 30%-ға көтерілді, содан кейін жаңа бағадан 20%-ға жеңілдік жасалды. Бастапқы баға 500 теңге болса, соңғы баға қандай?', 'Цена товара сначала была повышена на 30%, а затем на новую цену сделали скидку 20%. Если начальная цена 500 тенге, какова конечная цена?', '[{"text": "520", "correct": true}, {"text": "500", "correct": false}, {"text": "510", "correct": false}, {"text": "530", "correct": false}]', NULL),
  (39, '8 жұмысшы қабырғаны 15 күнде тұрғызады. 12 жұмысшы дәл сондай қабырғаны неше күнде тұрғызады?', '8 рабочих строят стену за 15 дней. За сколько дней 12 рабочих построят такую же стену?', '[{"text": "12", "correct": false}, {"text": "10", "correct": true}, {"text": "8", "correct": false}, {"text": "20", "correct": false}]', NULL),
  (40, '21 минут 1 сағаттың қанша бөлігін құрайды?', 'Какую часть часа составляют 21 минута?', '[{"text": "7/20", "correct": true}, {"text": "3/10", "correct": false}, {"text": "2/5", "correct": false}, {"text": "1/3", "correct": false}]', NULL)
) as v(question_number, text_kk, text_ru, choices, image_svg);